    // Configured recipe matrices with safe variations, tags, and pantry gaps
    const recipeDatabase = [
        {
            name: "Crispy Leftover Hash",
            tags: ["veg"],
            baseIngredients: ["potatoes", "peppers", "onions"],
            swaps: { "potatoes": ["sweet potatoes", "tater tots", "fries"], "peppers": ["broccoli", "zucchini"] },
            gaps: ["cooking oil", "salt/pepper"],
            directions: "Dice all ingredients. Fry in a hot skillet with oil until edges crisp. Top with an egg if available."
        },
        {
            name: "Spicy Stir-Fry Noodles",
            tags: ["heat", "veg"],
            baseIngredients: ["noodles", "broccoli", "onions"],
            swaps: { "noodles": ["rice", "quinoa"], "broccoli": ["peppers", "cabbage", "carrots"] },
            gaps: ["soy sauce", "chili oil / sriracha"],
            directions: "Sear veggies in a hot pan. Toss in your pre-cooked base noodles/rice. Stir-fry with soy sauce and chili oil until piping hot."
        },
        {
            name: "Quick Shredded Protein Tacos",
            tags: [],
            baseIngredients: ["chicken", "onions"],
            swaps: { "chicken": ["beef", "pork", "tofu", "beans"], "onions": ["peppers", "jalapenos"] },
            gaps: ["tortillas", "taco seasoning"],
            directions: "Shred your protein. Reheat in a skillet with a splash of water and taco seasoning. Serve inside warmed tortillas."
        },
        {
            name: "Thai-Style Peanut Peanut Curry",
            tags: ["allergen", "heat"],
            baseIngredients: ["chicken", "broccoli", "peppers"],
            swaps: { "chicken": ["tofu", "shrimp", "beef"], "broccoli": ["zucchini", "carrots"] },
            gaps: ["coconut milk", "peanut butter", "curry paste"],
            directions: "Simmer coconut milk, curry paste, and peanut butter. Drop in your leftovers and simmer until fully heated through."
        },
        {
            name: "Loaded Scramble / Frittata",
            tags: ["veg"],
            baseIngredients: ["onions", "peppers"],
            swaps: { "onions": ["scallions", "leeks"], "peppers": ["spinach", "mushrooms", "tomatoes"] },
            gaps: ["eggs", "butter / oil"],
            directions: "Sauté the veggies in butter until soft. Pour in beaten eggs and stir constantly over medium heat until set."
        }
    ];

    // Default leftover tracking pool
    let inventory = [
        { id: "potatoes", name: "potatoes", checked: true },
        { id: "peppers", name: "peppers", checked: true },
        { id: "onions", name: "onions", checked: true },
        { id: "chicken", name: "chicken", checked: false },
        { id: "broccoli", name: "broccoli", checked: false },
        { id: "noodles", name: "noodles", checked: false }
    ];

    function init() {
        renderIngredients();
        renderRecipes();
    }

    function renderIngredients() {
        const container = document.getElementById("ingredients-container");
        container.innerHTML = "";
        inventory.forEach((ing, index) => {
            const chip = document.createElement("label");
            chip.className = "ingredient-chip";

            const checkbox = document.createElement("input");
            checkbox.type = "checkbox";
            checkbox.checked = ing.checked;
            checkbox.addEventListener("change", () => {
                inventory[index].checked = checkbox.checked;
                renderRecipes();
            });

            const textSpan = document.createElement("span");
            textSpan.contentEditable = true;
            textSpan.textContent = ing.name;
            textSpan.addEventListener("blur", () => {
                inventory[index].name = textSpan.textContent.trim().toLowerCase();
                renderRecipes();
            });

            chip.appendChild(checkbox);
            chip.appendChild(textSpan);
            container.appendChild(chip);
        });
    }

    function renderRecipes() {
        const container = document.getElementById("recipes-container");
        container.innerHTML = "";

        const activeIngredients = inventory
            .filter(i => i.checked && i.name.length > 0)
            .map(i => i.name);

        let matchCount = 0;

        recipeDatabase.forEach(recipe => {
            // Evaluate dynamic match based on base items or their configured variants
            const matches = recipe.baseIngredients.filter(baseIng => {
                if (activeIngredients.includes(baseIng)) return true;
                const alternates = recipe.swaps[baseIng] || [];
                return alternates.some(alt => activeIngredients.includes(alt));
            });

            // Show card if it leverages at least one selected item
            if (matches.length > 0) {
                matchCount++;
                const card = document.createElement("div");
                card.className = "card";

                // Map active components used vs those needing swaps
                const displaySwaps = recipe.baseIngredients.map(baseIng => {
                    if (activeIngredients.includes(baseIng)) {
                        return `<strong>${baseIng}</strong>`;
                    }
                    const alternates = recipe.swaps[baseIng] || [];
                    const activeAlt = alternates.find(alt => activeIngredients.includes(alt));
                    if (activeAlt) {
                        return `<strong>${activeAlt}</strong> (swapped for ${baseIng})`;
                    }
                    return `${baseIng} [Missing/Optional]`;
                }).join(", ");

                // Tags markup
                const tagsMarkup = recipe.tags.map(t => {
                    let label = t;
                    if (t === 'veg') label = 'Vegetarian';
                    if (t === 'heat') label = 'Spicy';
                    if (t === 'allergen') label = 'Allergen (Peanut)';
                    return `<span class="tag ${t}">${label}</span>`;
                }).join("");

                const cardId = `recipe-${matchCount}`;

                card.innerHTML = `
                    <div class="card-header">
                        <div class="card-title">${recipe.name}</div>
                    </div>
                    <div class="tags">${tagsMarkup}</div>
                    <div class="list-title">Ingredients Used</div>
                    <div style="font-size: 0.85rem; margin-bottom: 6px;">${displaySwaps}</div>
                    <div class="list-title">Pantry Gaps</div>
                    <div class="gap" style="font-size: 0.85rem; margin-bottom: 6px;">${recipe.gaps.join(", ")}</div>
                    <div class="list-title">Quick Directions</div>
                    <div class="directions" id="${cardId}-dir">${recipe.directions}</div>
                    <div class="card-actions no-print">
                        <button class="secondary" onclick="copyCard('${cardId}', '${recipe.name}')">Copy</button>
                        <button class="secondary" onclick="printCard('${cardId}')">Print Card</button>
                    </div>
                `;
                container.appendChild(card);
            }
        });

        if (matchCount === 0) {
            container.innerHTML = `<div style="color: var(--text-muted); font-style: italic; padding: 12px 4px;">Select or edit leftovers above to generate meal cards.</div>`;
        }
    }

    function copyCard(id, title) {
        const text = document.getElementById(`${id}-dir`).innerText;
        navigator.clipboard.writeText(`${title}\n\nDirections:\n${text}`).then(() => {
            alert("Directions copied to clipboard.");
        });
    }

    function printCard(id) {
        window.print();
    }

    init();
</script>

</body>
</html>

