            swaps: { "noodles": ["rice", "quinoa"], "broccoli": ["peppers", "cabbage", "carrots"] },
            gaps: ["soy sauce", "chili oil / sriracha"],
            directions: "Sear veggies in a hot pan. Toss in your pre-cooked base noodles/rice. Stir-fry with soy sauce and chili oil until piping hot."
        },
        {
            name: "Quick Shredded Protein Tacos",
            tags: [],
            baseIngredients: ["chicken", "onions"],
            swaps: { "chicken": ["beef", "pork", "tofu", "beans"], "onions": ["peppers", "jalapenos"] },
            gaps: ["tortillas", "taco seasoning"],
            directions: "Shred your protein. Reheat in a skillet with a splash of water and taco seasoning. Serve inside warmed tortillas."
        },
        {
            name: "Thai-Style Peanut Curry",
            tags: ["allergen", "heat"],
            baseIngredients: ["chicken", "broccoli", "peppers"],
            swaps: { "chicken": ["tofu", "shrimp", "beef"], "broccoli": ["zucchini", "carrots"] },
            gaps: ["coconut milk", "peanut butter", "curry paste"],
            directions: "Simmer coconut milk, curry paste, and peanut butter. Drop in your leftovers and simmer until fully heated through."
        },
        {
            name: "Loaded Scramble / Frittata",
            tags: ["veg"],
            baseIngredients: ["onions", "peppers"],
            swaps: { "onions": ["scallions", "leeks"], "peppers": ["spinach", "mushrooms", "tomatoes"] },
            gaps: ["eggs", "butter / oil"],
            directions: "Sauté the veggies in butter until soft. Pour in beaten eggs and stir constantly over medium heat until set."
        }
    ];

    let inventory = [
        { id: "potatoes", name: "potatoes", checked: true },
        { id: "peppers", name: "peppers", checked: true },
        { id: "onions", name: "onions", checked: true },
        { id: "chicken", name: "chicken", checked: false },
        { id: "broccoli", name: "broccoli", checked: false },
        { id: "noodles", name: "noodles", checked: false }
    ];

    function init() {
        document.getElementById("btn-print-all").addEventListener("click", () => window.print());
        document.getElementById("btn-export").addEventListener("click", exportMealPlan);
        renderIngredients();
        renderRecipes();
    }

    function renderIngredients() {
        const container = document.getElementById("ingredients-container");
        container.textContent = "";

        inventory.forEach((ing, index) => {
            const chip = document.createElement("label");
            chip.className = "ingredient-chip";

            const checkbox = document.createElement("input");
            checkbox.type = "checkbox";
            checkbox.checked = ing.checked;
            checkbox.addEventListener("change", () => {
                inventory[index].checked = checkbox.checked;
                renderRecipes();
            });

            const textSpan = document.createElement("span");
            textSpan.contentEditable = "true";
            textSpan.textContent = ing.name;
            textSpan.addEventListener("blur", () => {
                inventory[index].name = textSpan.textContent.trim().toLowerCase();
                renderRecipes();
            });
            textSpan.addEventListener("keydown", (e) => {
                if (e.key === "Enter") {
                    e.preventDefault();
                    textSpan.blur();
                }
            });

            chip.appendChild(checkbox);
            chip.appendChild(textSpan);
            container.appendChild(chip);
        });
    }

    function getActiveRecipes(activeIngredients) {
        const matched = [];
        recipeDatabase.forEach(recipe => {
            const usedIngredients = [];
            let hasAtLeastOneMatch = false;

            recipe.baseIngredients.forEach(baseIng => {
                if (activeIngredients.includes(baseIng)) {
                    usedIngredients.push({ display: baseIng, isSwap: false });
                    hasAtLeastOneMatch = true;
                } else {
                    const alternates = recipe.swaps[baseIng] || [];
                    const activeAlt = alternates.find(alt => activeIngredients.includes(alt));
                    if (activeAlt) {
                        usedIngredients.push({ display: `${activeAlt} (swapped for ${baseIng})`, isSwap: true });
                        hasAtLeastOneMatch = true;
                    } else {
                        usedIngredients.push({ display: `${baseIng} [Missing/Optional]`, isSwap: false });
                    }
                }
            });

            if (hasAtLeastOneMatch) {
                matched.push({ recipe, usedIngredients });
            }
        });
        return matched;
    }

    function renderRecipes() {
        const container = document.getElementById("recipes-container");
        container.textContent = "";

        const activeIngredients = inventory
            .filter(i => i.checked && i.name.length > 0)
            .map(i => i.name);

        const currentMatches = getActiveRecipes(activeIngredients);
        const exportBtn = document.getElementById("btn-export");

        if (currentMatches.length === 0) {
            exportBtn.disabled = true;
            const emptyMsg = document.createElement("div");
            emptyMsg.className = "empty-message";
            emptyMsg.textContent = "Select or edit leftovers above to generate meal cards.";
            container.appendChild(emptyMsg);
            return;
        }

        exportBtn.disabled = false;

        currentMatches.forEach((match) => {
            const { recipe, usedIngredients } = match;

            const card = document.createElement("div");
            card.className = "card";

            const title = document.createElement("div");
            title.className = "card-title";
            title.textContent = recipe.name;
            card.appendChild(title);

            const tagsContainer = document.createElement("div");
            tagsContainer.className = "tags";
            recipe.tags.forEach(t => {
                const tagSpan = document.createElement("span");
                tagSpan.className = `tag ${t}`;
                if (t === 'veg') tagSpan.textContent = 'Vegetarian';
                if (t === 'heat') tagSpan.textContent = 'Spicy';
                if (t === 'allergen') tagSpan.textContent = 'Allergen (Peanut)';
                tagsContainer.appendChild(tagSpan);
            });
            card.appendChild(tagsContainer);

            const ingTitle = document.createElement("div");
            ingTitle.className = "list-title";
            ingTitle.textContent = "Ingredients Used";
            card.appendChild(ingTitle);

            const ingDesc = document.createElement("div");
            ingDesc.style.fontSize = "0.85rem";
            ingDesc.style.marginBottom = "6px";
            ingDesc.textContent = usedIngredients.map(i => i.display).join(", ");
            card.appendChild(ingDesc);

            const gapTitle = document.createElement("div");
            gapTitle.className = "list-title";
            gapTitle.textContent = "Pantry Gaps";
            card.appendChild(gapTitle);

            const gapDesc = document.createElement("div");
            gapDesc.className = "gap";
            gapDesc.style.fontSize = "0.85rem";
            gapDesc.style.marginBottom = "6px";
            gapDesc.textContent = recipe.gaps.join(", ");
            card.appendChild(gapDesc);

            const dirTitle = document.createElement("div");
            dirTitle.className = "list-title";
            dirTitle.textContent = "Quick Directions";
            card.appendChild(dirTitle);

            const dirDesc = document.createElement("div");
            dirDesc.className = "directions";
            dirDesc.textContent = recipe.directions;
            card.appendChild(dirDesc);

            const actionsDiv = document.createElement("div");
            actionsDiv.className = "card-actions no-print";

            const copyBtn = document.createElement("button");
            copyBtn.className = "secondary";
            copyBtn.textContent = "Copy";
            copyBtn.addEventListener("click", () => {
                const textBlock = `${recipe.name}\n\nIngredients: ${usedIngredients.map(i => i.display).join(", ")}\n\nPantry Gaps: ${recipe.gaps.join(", ")}\n\nDirections:\n${recipe.directions}`;
                navigator.clipboard.writeText(textBlock).then(() => {
                    alert(`Copied "${recipe.name}" card to clipboard.`);
                });
            });

            const printBtn = document.createElement("button");
            printBtn.className = "secondary";
            printBtn.textContent = "Print Card";
            printBtn.addEventListener("click", () => window.print());

            actionsDiv.appendChild(copyBtn);
            actionsDiv.appendChild(printBtn);
            card.appendChild(actionsDiv);

            container.appendChild(card);
        });
    }

    function exportMealPlan() {
        const activeIngredients = inventory
            .filter(i => i.checked && i.name.length > 0)
            .map(i => i.name);

        const currentMatches = getActiveRecipes(activeIngredients);
        if (currentMatches.length === 0) return;

        let fileText = "LEFTOVER SWAPPER - MEAL PLAN\n";
        fileText += `Generated on: ${new Date().toLocaleDateString()}\n`;
        fileText += `Selected Ingredients: ${activeIngredients.join(", ")}\n`;
        fileText += "========================================\n\n";

        currentMatches.forEach((match, idx) => {
            const { recipe, usedIngredients } = match;
            fileText += `${idx + 1}. ${recipe.name.toUpperCase()}\n`;
            fileText += `Tags: ${recipe.tags.join(", ")}\n`;
            fileText += `Ingredients Matrix: ${usedIngredients.map(i => i.display).join(", ")}\n`;
            fileText += `Pantry Gaps needed: ${recipe.gaps.join(", ")}\n`;
            fileText += `Directions: ${recipe.directions}\n`;
            fileText += "----------------------------------------\n\n";
        });

        const blob = new Blob([fileText], { type: "text/plain;charset=utf-8" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = `leftover-meal-plan-${new Date().toISOString().slice(0,10)}.txt`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    }

    init();
</script>

